const b = $json.body ?? {};
if (!b.company_id || !b.payload?.source || (!b.payload?.phone && !b.payload?.email)) {
  return [{ json: { _error: { code: 'invalid_input', message: 'company_id, payload.source and phone or email are required', retryable: false } } }];
}
return [{ json: {
  company_id: b.company_id,
  request_id: b.request_id ?? crypto.randomUUID(),
  source: 'webhook',
  channel: 'internal',
  payload: b.payload,
  started_at: Date.now(),
} }];

// Config-driven scoring: weights + thresholds live in vertical/tenant config, never in code.
const base = $('Validate').first().json;
const ctx = $json.data?.ctx ?? {};
const p = base.payload;

const scoring = ctx.lead_scoring ?? {
  weights: { has_phone: 20, has_email: 10, has_service_interest: 30, timeframe_asap: 30, timeframe_this_month: 15, source_missed_call: 20, source_referral: 25 },
  routes: [ { min: 60, route: 'instant_follow_up' }, { min: 30, route: 'nurture' }, { min: 0, route: 'log_only' } ],
};

const w = scoring.weights;
let score = 0;
const reasons = [];
const add = (points, reason) => { if (points) { score += points; reasons.push(`${reason} (+${points})`); } };

add(p.phone ? w.has_phone ?? 0 : 0, 'has phone');
add(p.email ? w.has_email ?? 0 : 0, 'has email');
add(p.service_interest ? w.has_service_interest ?? 0 : 0, 'named a service');
if (p.timeframe === 'asap') add(w.timeframe_asap ?? 0, 'wants it asap');
if (p.timeframe === 'this_month') add(w.timeframe_this_month ?? 0, 'this month');
add(w[`source_${p.source}`] ?? 0, `source: ${p.source}`);

score = Math.max(0, Math.min(100, score));
const route = (scoring.routes ?? []).sort((a, b2) => b2.min - a.min).find(r => score >= r.min)?.route ?? 'log_only';

return [{ json: { ...base, lead_score: score, reasons, route } }];
